import{_ as a,C as i,o,c as n,a2 as l,b as s,w as e,a as d,E,a3 as g}from"./chunks/framework.CZGNF-7T.js";const D=JSON.parse('{"title":"공문 발송 관리 (사용자 가이드)","description":"","frontmatter":{},"headers":[],"relativePath":"approval/official-letter.md","filePath":"approval/official-letter.md","lastUpdated":1789235971000}'),C={name:"approval/official-letter.md"};function c(B,t,A,u,h,f){const r=i("Mermaid");return o(),n("div",null,[t[1]||(t[1]=l('<h1 id="공문-발송-관리-사용자-가이드" tabindex="-1">공문 발송 관리 (사용자 가이드) <a class="header-anchor" href="#공문-발송-관리-사용자-가이드" aria-label="Permalink to &quot;공문 발송 관리 (사용자 가이드)&quot;">​</a></h1><blockquote><p><strong>공문 발송 관리</strong>는 대외 기관, 발주처, 협력업체 등에 발신하는 공식 서한(공문서)을 표준 A4 서식으로 작성하고, 전자결재 품의 또는 직접 발송 절차를 거쳐 발송 대장에 체계적으로 등록·보관하는 시스템입니다.</p></blockquote><ul><li><strong>메뉴 위치</strong>: <code>대외 공문 관리 &gt; 발송 공문 관리</code> (<code>/official-letter/outbound</code>)</li><li><strong>적용 대상</strong>: 본사 기안자, 현장소장, 프로젝트 공무/공사 담당자 등 대외 공문 발송 업무를 수행하는 모든 사용자</li></ul><h2 id="_1-공문서-작성-및-실시간-a4-미리보기" tabindex="-1">1. 공문서 작성 및 실시간 A4 미리보기 <a class="header-anchor" href="#_1-공문서-작성-및-실시간-a4-미리보기" aria-label="Permalink to &quot;1. 공문서 작성 및 실시간 A4 미리보기&quot;">​</a></h2><p>공문 작성 화면은 왼쪽의 <strong>입력 폼</strong>과 오른쪽의 **실시간 A4 미리보기(Live Preview)**로 구성되어 있어, 작성 중인 문서가 실제 출력 시 어떻게 인쇄될지 즉시 확인하며 작성할 수 있습니다.</p>',5)),(o(),s(g,null,{default:e(()=>[E(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%88%98%EC%8B%A0%EC%B2%98%20%EB%B0%8F%20%EC%A0%9C%EB%AA%A9%3Cbr%3E(%EC%88%98%EC%8B%A0%2C%20%EA%B2%BD%EC%9C%A0%2C%20%EC%B0%B8%EC%A1%B0%2C%20%EC%A0%9C%EB%AA%A9)%22%5D%20--%3E%20B%5B%222.%20%EB%B3%B8%EB%AC%B8%20%EB%B0%8F%20%EB%B6%99%EC%9E%84%20%EC%84%9C%EB%A5%98%3Cbr%3E(PDF%20%EA%B6%8C%EC%9E%A5%20%EC%B2%A8%EB%B6%80%20%2F%20%ED%85%8D%EC%8A%A4%ED%8A%B8)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EB%B0%9C%EC%86%A1%20%EB%B0%A9%EC%8B%9D%20%26%20%EC%9D%B8%EC%9E%A5%20%EC%84%A0%ED%83%9D%3Cbr%3E(%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%20%EC%83%81%EC%8B%A0%20vs%20%EC%88%98%EB%8F%99%20%EC%A7%81%EC%A0%91%EB%B0%9C%EC%86%A1)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%8B%A4%EC%8B%9C%EA%B0%84%20A4%20%ED%94%84%EB%A6%AC%EB%B7%B0%20%ED%99%95%EC%9D%B8%3Cbr%3E(%EB%B9%84%EC%9C%A8%20210%3A297%20%EA%B3%A0%EC%A0%95)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EC%A0%80%EC%9E%A5%20%EB%B0%8F%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%20%EC%83%81%EC%8B%A0%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h3 id="상단-서식-4행-고정" tabindex="-1">상단 서식 (4행 고정) <a class="header-anchor" href="#상단-서식-4행-고정" aria-label="Permalink to &quot;상단 서식 (4행 고정)&quot;">​</a></h3><ul><li><strong>수 신</strong>: 공문을 정식으로 접수하는 기관명 또는 법인명 (필수)</li><li><strong>경 유</strong>: 최종 수신처에 도달하기 전 중간에 경유하는 부서나 감리단 등 (없을 시 빈칸)</li><li><strong>참 조</strong>: 공문 내용을 참조해야 하는 직위나 부서 (예: <code>대표이사 귀하</code>, <code>공사담당자 앞</code>)</li><li><strong>시행 일자</strong>: 공문의 공식 발신 일자</li><li><strong>제 목</strong>: 공문의 핵심 내용을 간결하고 명확하게 기술 (필수)</li></ul><h3 id="본문-및-붙임-첨부-서류" tabindex="-1">본문 및 붙임(첨부) 서류 <a class="header-anchor" href="#본문-및-붙임-첨부-서류" aria-label="Permalink to &quot;본문 및 붙임(첨부) 서류&quot;">​</a></h3><ul><li><strong>본문 내용</strong>: 공문의 전문을 입력하며, 줄바꿈은 인쇄 시 그대로 반영됩니다. 문단을 구분하려면 빈 줄을 추가하십시오.</li><li><strong>붙임(첨부) 방식 선택</strong>: <ul><li><strong>파일 직접 첨부 (권장)</strong>: <ul><li>공문서 위변조 방지 및 수신처의 원활한 열람을 위해 <strong>PDF 파일 형식</strong> 첨부를 강력히 권장합니다. (필요 시 HWP, 엑셀, 이미지 등도 첨부 가능)</li><li>파일별로 <strong>붙임 명칭</strong>(예: <code>사업계획서</code>, <code>설계도면</code>)과 <strong>수량/부수</strong>(예: <code>1부</code>, <code>1식</code>)를 직접 기입할 수 있습니다.</li></ul></li><li><strong>텍스트 직접 입력</strong>: 실물 서류를 인편이나 등기로 동봉하여 발송할 경우 등, 파일 없이 인쇄용 목록만 표기할 때 사용합니다.</li></ul></li></ul><h3 id="발신-명의-및-인장-직인-선택" tabindex="-1">발신 명의 및 인장(직인) 선택 <a class="header-anchor" href="#발신-명의-및-인장-직인-선택" aria-label="Permalink to &quot;발신 명의 및 인장(직인) 선택&quot;">​</a></h3><ul><li><strong>전자결재 상신 발송</strong>: 결재선 승인 완료 시 공문서 하단 결재란에 <code>담당 [기안자] → [검토자] → [직책] [최종승인권자]</code>가 표준 형식으로 자동 배치되며, 최종 승인권자 바로 위에 승인/전결 일자가 표기됩니다. (대표이사 단독 기안 시 &#39;담당&#39; 중복 없이 대표이사 단독 표기)</li><li><strong>수동(직접) 발송</strong>: 전자결재 없이 직접 발송하는 공문으로, <strong>기안/담당자명</strong> 및 <strong>담당 직위</strong>를 입력합니다. (하단 결재란에 <code>담당 [기안자]</code>와 우측의 대표이사 서명이 배치됩니다)</li><li><strong>날인 인감(직인) 선택</strong>: <ul><li><code>등록된 회사 인장 (전자날인)</code>: 선택 시 인장 이미지가 PDF에 자동 합성되어 출력됩니다.</li><li><code>인장 미선택 / (직인생략 / 출력 후 실물날인)</code>: 일반 안내문 등 직인을 생략하거나, 출력 후 실물 인감을 직접 날인하여 발송할 때 선택합니다.</li></ul></li></ul><h2 id="_2-전자결재-상신-및-승인-흐름" tabindex="-1">2. 전자결재 상신 및 승인 흐름 <a class="header-anchor" href="#_2-전자결재-상신-및-승인-흐름" aria-label="Permalink to &quot;2. 전자결재 상신 및 승인 흐름&quot;">​</a></h2><p>공문 작성 완료 후 <strong>[전자결재 상신]</strong> 버튼을 클릭하면, 공문 발송 품의서가 전자결재 시스템으로 자동 접수됩니다.</p><ul><li><strong>인장별 전결 규정 자동 연동</strong>: <ul><li><strong>대표이사 법인인감</strong> 선택 시: 최종 승인권자가 반드시 대표이사로 구성됩니다.</li><li><strong>현장소장 직인/부서인감</strong> 선택 시: 사전 등록된 인장 규정에 따라 현장소장/부서장 선에서 전결 승인 처리가 가능합니다.</li></ul></li><li><strong>최종 승인 완료</strong>: 전자결재가 최종 승인되면 공식 문서번호가 확정 채번되며, 시스템 공식 PDF가 생성됩니다.</li></ul><h2 id="_3-공문-발송-및-pdf-스캔본-증빙-관리-정책" tabindex="-1">3. 공문 발송 및 PDF(스캔본) 증빙 관리 정책 <a class="header-anchor" href="#_3-공문-발송-및-pdf-스캔본-증빙-관리-정책" aria-label="Permalink to &quot;3. 공문 발송 및 PDF(스캔본) 증빙 관리 정책&quot;">​</a></h2><p>공문이 승인되거나 발송 준비가 완료된 후 대외 발송을 처리하고 증빙을 보관하는 기준입니다.</p><h3 id="전자-직인-pdf-vs-실물-날인-스캔본-pdf" tabindex="-1">전자 직인 PDF vs 실물 날인 스캔본 PDF <a class="header-anchor" href="#전자-직인-pdf-vs-실물-날인-스캔본-pdf" aria-label="Permalink to &quot;전자 직인 PDF vs 실물 날인 스캔본 PDF&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">발송 방식</th><th style="text-align:left;">발송 및 증빙 처리 절차</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>이메일 / 전자팩스 발송</strong></td><td style="text-align:left;">시스템에서 자동 생성된 전자 직인 PDF를 다운로드하여 상대방에게 전송하고, 해당 PDF를 시스템에 최종 발송본으로 유지합니다.</td></tr><tr><td style="text-align:left;"><strong>등기우편 / 인편 직접 교부 (실물 날인)</strong></td><td style="text-align:left;">인장을 미선택하여 출력한 후 <strong>실물 도장을 직접 날인</strong>하여 발송합니다. 발송 후 **실물 날인된 종이를 스캔(PDF)**하여 공문 상세 화면에서 <code>[실물날인 스캔본(PDF) 업로드/교체]</code> 기능을 통해 등록합니다.</td></tr></tbody></table><h3 id="⚠️-발송-완료-후-증빙-보호-정책-중요" tabindex="-1">⚠️ 발송 완료 후 증빙 보호 정책 (중요) <a class="header-anchor" href="#⚠️-발송-완료-후-증빙-보호-정책-중요" aria-label="Permalink to &quot;⚠️ 발송 완료 후 증빙 보호 정책 (중요)&quot;">​</a></h3><ul><li><strong>발송 완료 처리</strong>: 등기번호, 발송방법(이메일, 등기, 인편 등), 발송완료일시를 등록하면 공문이 <strong>발송 완료</strong> 상태로 전환됩니다.</li><li><strong>PDF 재생성 전면 금지</strong>: <ul><li>발송 완료된 공문서는 법적 대항력 및 증빙 무결성 유지를 위해 <strong>수퍼유저를 포함하여 시스템 PDF 재생성이 무조건 전면 금지</strong>됩니다.</li><li>이를 통해 이미 실제 발송된 스캔본 증빙이 실수로 시스템 기본 양식으로 덮어씌워져 유실되는 참사를 원천 차단합니다.</li></ul></li><li><strong>스캔본 사후 교체 권한</strong>: <ul><li>발송 완료 후 스캔본을 보완하거나 교체해야 하는 경우, 데이터 보호를 위해 **관리자(슈퍼유저/워크매니저)**만 교체할 수 있습니다.</li></ul></li></ul>',15))])}const p=a(C,[["render",c]]);export{D as __pageData,p as default};
